package com.signalarchive.app

import java.io.File

/** Only temporary files generated by the embedded exporter may be removed here. */
internal object IntermediateExports {
    fun checked(filesDir: File, path: String): File {
        val root = File(filesDir, "telegram-engine/exports").canonicalFile.toPath()
        val file = File(path).canonicalFile
        require(file.toPath().startsWith(root) && file.isFile) { "Неверный путь экспорта" }
        return file
    }
    fun remove(files: Iterable<File>) { files.forEach { runCatching { it.delete() } } }
}
